// Frozen oracle for keepa-mcp product-summary semantics, executed from the unmodified pinned donor.
// node keepa_summary_oracle.mjs <keepa-mcp checkout at 84c2145c> <typescript.js> <node_modules dir with zod> <out.json>
// Every donor src/*.ts module is transpiled verbatim (types erased) into a scratch directory and
// buildProductSummary is called on generated Keepa product objects; no network code runs.
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { pathToFileURL, fileURLToPath } from 'node:url';

const [donor, tsPath, nodeModules, out] = process.argv.slice(2);
const commit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: donor, encoding: 'utf8' }).trim();
if (commit !== '84c2145c9f74bd29a91a19b12c24abe1c2535223') throw Error('unexpected donor commit ' + commit);
if (execFileSync('git', ['status', '--porcelain'], { cwd: donor, encoding: 'utf8' }).trim()) throw Error('donor checkout modified');
const ts = (await import(pathToFileURL(tsPath))).default;
const work = fs.mkdtempSync(path.join(os.tmpdir(), 'keepa-oracle-'));
fs.writeFileSync(path.join(work, 'package.json'), '{"type":"module"}');
fs.symlinkSync(path.resolve(nodeModules), path.join(work, 'node_modules'));
const evidence = [];
for (const file of ['constants.ts', 'types.ts', 'services/keepa-values.ts', 'services/keepa-client.ts', 'tools/get-product.ts']) {
  const source = execFileSync('git', ['show', `${commit}:src/${file}`], { cwd: donor });
  evidence.push({ path: 'src/' + file, blob_hash: execFileSync('git', ['rev-parse', `${commit}:src/${file}`], { cwd: donor, encoding: 'utf8' }).trim(), sha256: crypto.createHash('sha256').update(source).digest('hex') });
  const js = ts.transpileModule(source.toString('utf8'), { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 } }).outputText;
  fs.mkdirSync(path.dirname(path.join(work, file)), { recursive: true });
  fs.writeFileSync(path.join(work, file.replace(/\.ts$/, '.js')), js);
}
const { buildProductSummary } = await import(pathToFileURL(path.join(work, 'tools/get-product.js')));

let seed = 0x6b65657;
const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
const slots = [0, 1, 3, 11, 16, 17, 18];
const value = () => [-1, 0, 1, random() % 100000][random() % 4];
const cases = [];
const add = (id, product) => cases.push({ case_id: id, product, expected: buildProductSummary(product) });
add('empty', { asin: 'B000000001' });
add('rank-zero', { asin: 'B000000002', stats: { current: [null, null, null, 0] } });
add('reviews-fallback', { asin: 'B000000003', reviews: { rating: 45, reviewCount: 120 } });
add('stats-over-reviews', { asin: 'B000000004', stats: { current: Object.assign(Array(18).fill(null), { 16: 41, 17: 7 }) }, reviews: { rating: 45, reviewCount: 120 } });
for (let i = 0; i < 300; i++) {
  const p = { asin: 'B0' + String(i).padStart(8, '0') };
  if (random() % 2) { p.stats = { current: Array(19).fill(null) }; for (const s of slots) if (random() % 2) p.stats.current[s] = value(); }
  if (random() % 2) { p.csv = Array(19).fill(null); for (const s of slots) if (random() % 2) { const stride = s === 18 ? 3 : 2; const series = []; for (let n = 0, c = random() % 4; n < c; n++) { series.push(n * 60, value()); if (stride === 3) series.push(random() % 500); } p.csv[s] = series; } }
  if (random() % 2) { p.current = Array(19).fill(null); for (const s of slots) if (random() % 2) p.current[s] = value(); }
  if (random() % 3 === 0) p.reviews = { rating: value(), reviewCount: value() };
  if (random() % 4 === 0) p.newOfferCount = value();
  if (random() % 2) p.title = 'T' + i;
  if (random() % 2) p.brand = 'B' + i;
  cases.push({ case_id: 'seeded-' + i, product: p, expected: buildProductSummary(p) });
}
const generator = fs.readFileSync(fileURLToPath(import.meta.url));
fs.writeFileSync(out, JSON.stringify({ donor_id: 'purahmanian--keepa-mcp', commit_sha: commit, license: 'MIT', symbol: 'buildProductSummary',
  oracle: 'UNMODIFIED_PINNED_DONOR_TRANSPILED_TYPES_ERASED', node: process.version, typescript: ts.version, source_evidence: evidence,
  generator_sha256: crypto.createHash('sha256').update(generator).digest('hex'), generator_source: generator.toString('utf8'), cases }, null, 1) + '\n');
console.log(cases.length, 'cases');
